-- Venue Live Guest "Ulang Tahun Princess Royal Ballroom". Aditif & idempoten. Jalankan SETELAH admin-live-event-aqiqah.sql (jenis acara princessroyal), admin-live-theme.sql, admin-live-decor.sql, admin-live-decor-avatars.sql, dan admin-live-decor-garden-layout.sql (skrip tata letak itu melewati venue ini karena ukuran/posisi dekornya diatur sendiri).
insert into public.live_venues (key, name, event_type, areas, max_guests, active, sort, bg_pos, nm_theme)
select 'princessroyal', 'Ulang Tahun Princess Royal Ballroom', 'princessroyal', coalesce((select areas from public.live_venues where key = 'little-ballerina'), '[]'::jsonb), 300, false, 172, 'center 38%',
  $t${"name":"Princess Royal Ballroom","orn":"diamond","ui":{"ivory":"#FFF7FD","white":"#FFFFFF","soft":"#F5DFF3","soft2":"#D9B3E6","accent":"#B35FC4","deep":"#6A2F7C","ink":"#532562","mute":"#A485AE","line":"#EBD3EE","serif":"\"Fredoka\",system-ui,sans-serif","sans":"Inter,system-ui,sans-serif","rad":18,"btnr":14,"btnt":"none","btnls":".02em"},"mono":{"font":"\"Fredoka\",system-ui,sans-serif","it":0,"paper":"#FFFAFF","ink":"#532562","accent":"#B35FC4","gold":"#C9A24A","leaf":"#F5DFF3","hbg":"rgba(255,247,253,.94)","hline":"#C9A24A","motif":"diamond"},"hud":{"bg":"rgba(83,37,98,.9)","acc":"#FFD7F3","on":"#532562"},"scr":{"wine":"#6A2F7C","veil":"255,247,253"}}$t$::jsonb
where not exists (select 1 from public.live_venues where key = 'princessroyal');
